mapper.insert:
/* BatchAlarmMapper.insertAlarm 알람을 등록한다. */
INSERT INTO TB_ALRM_L (
    ALRM_SN, RCVR_ID, ALRM_TYPE_CD, ALRM_TITL_NM, ALRM_CONT, PRGM_ID, CFM_YN,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{alrmSn}, #{rcvrId}, #{alrmTypeCd}, #{alrmTitlNm}, #{alrmCont}, #{prgmId}, 'N',
    #{regrId}, #{regDt}, #{regrId}, #{regDt}
)

mapper.select:
/* BatchAlarmMapper.selectExistingUsrIdList 사용자 테이블에 있는 사용자ID만 조회한다 (알람 수신자 검증). */
SELECT USR_ID
FROM TB_USR_M
WHERE USR_ID IN

    #{usrId}

mapper.insert:
/* BatchAlarmMapper.insertBatchAlarmRcvr 배치직무의 알람 수신자를 등록한다. */
INSERT INTO TB_DSPT_ALRM_RCVR_R (
    JOB_ID, USR_ID,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{jobId}, #{usrId},
    #{regrId}, CURRENT_TIMESTAMP, #{regrId}, CURRENT_TIMESTAMP
)

mapper.delete:
/* BatchAlarmMapper.deleteBatchAlarmRcvrByJobId 배치직무의 알람 수신자를 모두 삭제한다 (배치직무 삭제, 수신자 저장 시 전체 교체). */
DELETE FROM TB_DSPT_ALRM_RCVR_R
WHERE JOB_ID = #{jobId}
